from PIL import Image
import numpy as np
from scipy.ndimage import median_filter
im=np.asarray(Image.open('/app/target.png')).astype(np.int16)
pal=np.array([[190,191,170],[206,173,135],[149,171,164],[191,147,114],[113,144,149],[155,132,113],[81,133,156],[121,103,93],[72,105,120],[20,90,129]],np.int16)
white=np.array([248,245,237]); d=np.linalg.norm(im[:,:,None,:]-pal,axis=3); md=d.min(2); lab=d.argmin(2).astype(np.int16); dw=np.linalg.norm(im-white,axis=2); lab[dw+5<md]=-1
for filt in [1,3,5,7]:
 L=lab if filt==1 else median_filter(lab,size=filt)
 print('filter',filt)
 for step in [24,26,28,30,32]:
  for minrun in [24,32,40,48,56,64,72]:
   count=total=0
   for v in range(step//2,1024,step):
    r=L[v]; cuts=np.r_[0,np.where(r[1:]!=r[:-1])[0]+1,1024]
    for a,b in zip(cuts[:-1],cuts[1:]):
     n=b-a
     if r[a]>=0 and n>=minrun:
      count+=1;total+=n
   if minrun in [32,48,64]: print(step,minrun,count,total,'cover rough',round(total*32/1024**2,3))
