from PIL import Image,ImageDraw
import numpy as np
from scipy.ndimage import median_filter
im=np.asarray(Image.open('/app/target.png')).astype(np.int16)
pal=np.array([[190,191,170],[206,173,135],[149,171,164],[191,147,114],[113,144,149],[155,132,113],[81,133,156],[121,103,93],[72,105,120],[20,90,129]],np.int16)
w=np.array([248,245,237]); ds=np.linalg.norm(im[:,:,None,:]-pal,axis=3); mn=ds.min(2);raw=ds.argmin(2).astype(np.int16);wm=np.linalg.norm(im-w,axis=2)+5<mn
lab=median_filter(raw,size=3);lab[wm]=-1;T=lab.copy();T[T<0]=10
for width in [30,32,34,36]:
 for step in [8,9,10,11,12]:
  for minrun in [40,48,56,64,72,80]:
   strokes=[]
   for v in range(step//2,1024,step):
    row=lab[v];cuts=np.r_[0,np.where(row[1:]!=row[:-1])[0]+1,1024]
    for a,b in zip(cuts[:-1],cuts[1:]):
     if row[a]<0 or b-a<minrun: continue
     r=width//2-1;aa=a+r;bb=b-1-r
     if aa<=bb: strokes.append((v,aa,bb,int(row[a])))
   if len(strokes)>407:continue
   c=Image.new('L',(1024,1024),10);d=ImageDraw.Draw(c)
   for v,a,b,k in strokes:
    d.line((a,v,b,v),fill=k,width=width);rr=width//2;d.ellipse((a-rr,v-rr,a+rr,v+rr),fill=k);d.ellipse((b-rr,v-rr,b+rr,v+rr),fill=k)
   O=np.asarray(c);op=O<10;tp=T<10;iou=(op&tp).sum()/(op|tp).sum();cls=(O[tp]==T[tp]).mean();rec=(op&tp).sum()/tp.sum()
   if iou>.945 or (step==10 and minrun in [40,48,56,64,72]): print(width,step,minrun,len(strokes),round(iou,3),round(rec,3),round(cls,3))
